package org.apache.commons.lang3.text;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;

import org.apache.commons.lang3.AbstractLangTest;
import org.junit.jupiter.api.Test;

/**
 * Tests {@link StrMatcher#splitMatcher()}.
 *
 * <p>The split matcher recognises the same delimiters as {@code StringTokenizer}:
 * space, tab, newline, carriage return and form-feed. For each of these characters
 * {@code isMatch} returns 1 (a one-character match); for every other character it
 * returns 0 (no match).</p>
 */
@Deprecated
public class StrMatcherTest_testSplitMatcher extends AbstractLangTest {

    /**
     * A sample buffer whose characters exercise both matching and non-matching cases.
     * The split delimiters (tab, space, newline, carriage return, form-feed) sit at
     * indices 3, 5, 7, 8 and 9; every other index holds a non-delimiter character,
     * including the NUL character at index 10.
     *
     * <p>This is exactly {@code "0,1\t2 3\n\r\f�'\""} spelled out character by
     * character so the meaning of each index is explicit.</p>
     */
    private static final char[] SAMPLE_BUFFER = {
        '0',   // index 0  - not a delimiter
        ',',   // index 1  - not a delimiter
        '1',   // index 2  - not a delimiter
        '\t',  // index 3  - tab (delimiter)
        '2',   // index 4  - not a delimiter
        ' ',   // index 5  - space (delimiter)
        '3',   // index 6  - not a delimiter
        '\n',  // index 7  - newline (delimiter)
        '\r',  // index 8  - carriage return (delimiter)
        '\f',  // index 9  - form-feed (delimiter)
        '\0',  // index 10 - NUL (not a delimiter)
        '\'',  // index 11 - single quote (not a delimiter)
        '"'    // index 12 - double quote (not a delimiter)
    };

    /** Value returned by {@code isMatch} when the character is a split delimiter. */
    private static final int MATCH = 1;

    /** Value returned by {@code isMatch} when the character is not a split delimiter. */
    private static final int NO_MATCH = 0;

    @Test
    void testSplitMatcher() {
        final StrMatcher matcher = StrMatcher.splitMatcher();

        // splitMatcher() always returns the same shared singleton instance.
        assertSame(matcher, StrMatcher.splitMatcher());

        assertEquals(NO_MATCH, matcher.isMatch(SAMPLE_BUFFER, 2),  "'1' is not a delimiter");
        assertEquals(MATCH,    matcher.isMatch(SAMPLE_BUFFER, 3),  "tab is a delimiter");
        assertEquals(NO_MATCH, matcher.isMatch(SAMPLE_BUFFER, 4),  "'2' is not a delimiter");
        assertEquals(MATCH,    matcher.isMatch(SAMPLE_BUFFER, 5),  "space is a delimiter");
        assertEquals(NO_MATCH, matcher.isMatch(SAMPLE_BUFFER, 6),  "'3' is not a delimiter");
        assertEquals(MATCH,    matcher.isMatch(SAMPLE_BUFFER, 7),  "newline is a delimiter");
        assertEquals(MATCH,    matcher.isMatch(SAMPLE_BUFFER, 8),  "carriage return is a delimiter");
        assertEquals(MATCH,    matcher.isMatch(SAMPLE_BUFFER, 9),  "form-feed is a delimiter");
        assertEquals(NO_MATCH, matcher.isMatch(SAMPLE_BUFFER, 10), "NUL character is not a delimiter");
    }
}
